# Prisoner's dilemma payoffs (row, col); C=cooperate, D=defect
pay = {('C','C'):(3,3),('C','D'):(0,5),('D','C'):(5,0),('D','D'):(1,1)}
for a in 'CD':
    for b in 'CD':
        ra = all(pay[(a,b)][0] >= pay[(x,b)][0] for x in 'CD')
        cb = all(pay[(a,b)][1] >= pay[(a,y)][1] for y in 'CD')
        if ra and cb: print('Nash equilibrium:', a, b)
